  it('bad index fires in a nested array', () => {
    expectOpError({ a: [{ x: 1 }] }, { op: 'test', path: '/a/01/x', value: 1 }, 'bad index');
  });

  it('first failing token decides the reason', () => {
    expectOpError({ a: [1] }, { op: 'test', path: '/a/5/01', value: 1 }, 'path not found');
