import { describe, it } from 'node:test';
import assert from 'node:assert/strict';
import { parsePointer, applyPatch, PatchError } from '../jsonpatch.mjs';

// ---- helpers ----

function expectPatchError(fn, message, index) {
  assert.throws(fn, (err) => {
    assert.ok(err instanceof PatchError, 'instanceof PatchError');
    assert.ok(err instanceof Error, 'instanceof Error');
    assert.strictEqual(err.name, 'PatchError');
    assert.strictEqual(err.message, message);
    assert.strictEqual(err.index, index);
    return true;
  });
}

function expectOpError(doc, op, reason, index = 0) {
  expectPatchError(() => applyPatch(doc, [op]), `operation ${index}: ${reason}`, index);
}

function expectPatchFail(doc, patch, reason, index) {
  expectPatchError(() => applyPatch(doc, patch), `operation ${index}: ${reason}`, index);
}

function one(doc, op) {
  return applyPatch(doc, [op]);
}

function deepFreeze(value) {
  if (typeof value === 'object' && value !== null && !Object.isFrozen(value)) {
    Object.freeze(value);
    for (const key of Reflect.ownKeys(value)) deepFreeze(value[key]);
  }
  return value;
}

function nest(depth) {
  let value = [];
  for (let i = 1; i < depth; i++) value = [value];
  return value;
}

function depthOf(value) {
  let depth = 0;
  let cur = value;
  while (Array.isArray(cur)) {
    depth++;
    cur = cur[0];
  }
  return depth;
}

function assertNoSharedArrays(a, b) {
  let x = a;
  let y = b;
  while (Array.isArray(x)) {
    assert.notStrictEqual(x, y);
    x = x[0];
    y = y[0];
  }
}

// ---- parsePointer ----

describe('parsePointer decoding', () => {
  const cases = [
    ['', []],
    ['/', ['']],
    ['/a//b/', ['a', '', 'b', '']],
    ['/~01', ['~1']],
    ['/~10', ['/0']],
    ['/a~0b~1c', ['a~b/c']],
    ['/~0~1', ['~/']],
  ];
  for (const [input, expected] of cases) {
    it(`decodes ${JSON.stringify(input)}`, () => {
      assert.deepStrictEqual(parsePointer(input), expected);
    });
  }

  it('returns a fresh array each call', () => {
    const first = parsePointer('/a/b');
    const second = parsePointer('/a/b');
    assert.notStrictEqual(first, second);
    first.push('zzz');
    first[0] = 'changed';
    assert.deepStrictEqual(parsePointer('/a/b'), ['a', 'b']);
    const e1 = parsePointer('');
    e1.push('x');
    assert.deepStrictEqual(parsePointer(''), []);
  });
});

describe('parsePointer errors', () => {
  for (const input of ['a', ' /a', '/~', '/~2', '/a~', '/~/', '#/a']) {
    it(`SyntaxError for ${JSON.stringify(input)}`, () => {
      assert.throws(() => parsePointer(input), { name: 'SyntaxError', message: 'invalid pointer' });
      assert.throws(() => parsePointer(input), (e) => e instanceof SyntaxError);
    });
  }

  const nonStrings = [
    ['undefined', undefined],
    ['null', null],
    ['number', 1],
    ['array', ['/a']],
    ['String object', new String('/a')],
    ['object', {}],
    ['boolean', true],
  ];
  for (const [label, input] of nonStrings) {
    it(`TypeError for ${label}`, () => {
      assert.throws(() => parsePointer(input), { name: 'TypeError', message: 'pointer must be a string' });
      assert.throws(() => parsePointer(input), (e) => e instanceof TypeError);
    });
  }
});

// ---- applyPatch: patch and operation form ----

describe('applyPatch patch argument', () => {
  const bad = [
    ['null', null],
    ['undefined', undefined],
    ['object', {}],
    ['string', '[]'],
    ['String object', new String('')],
    ['length object', { length: 0 }],
    ['array-like', { 0: { op: 'test', path: '', value: 1 }, length: 1 }],
    ['typed array', new Uint8Array(0)],
  ];
  for (const [label, patch] of bad) {
    it(`rejects ${label}`, () => {
      expectPatchError(() => applyPatch({}, patch), 'patch must be an array', null);
    });
  }
});

describe('applyPatch operation is an object', () => {
  const bad = [
    ['null', null],
    ['array', []],
    ['number', 5],
    ['string', 'x'],
    ['function', () => {}],
    ['undefined', undefined],
  ];
  for (const [label, op] of bad) {
    it(`rejects ${label}`, () => expectOpError({}, op, 'not an object'));
  }

